const refreshWorkflowReadyTasks = `-- name: RefreshWorkflowReadyTasks :execrows
UPDATE workflow_tasks
SET state = 'ready', revision = revision + 1, updated_at = ?1
WHERE workflow_tasks.workflow_id = ?2
  AND workflow_tasks.state = 'pending'
  AND EXISTS (
      SELECT 1 FROM workflows
      WHERE id = ?2 AND state = 'active'
  )
  AND NOT EXISTS (
      SELECT 1
      FROM workflow_edges e
      JOIN workflow_tasks predecessor
        ON predecessor.workflow_id = e.workflow_id AND predecessor.id = e.from_task_id
      WHERE e.workflow_id = ?2
        AND e.to_task_id = workflow_tasks.id
        AND predecessor.state <> 'succeeded'
  )
  AND NOT EXISTS (
      SELECT 1 FROM workflow_attempts a
      WHERE a.workflow_id = workflow_tasks.workflow_id
        AND a.task_id = workflow_tasks.id
        AND a.state IN ('claimed', 'running', 'settling', 'unknown')
  )
`

type RefreshWorkflowReadyTasksParams struct {
	UpdatedAt  time.Time
	WorkflowID domain.WorkflowID
}

func (q *Queries) RefreshWorkflowReadyTasks(ctx context.Context, arg RefreshWorkflowReadyTasksParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, refreshWorkflowReadyTasks, arg.UpdatedAt, arg.WorkflowID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const resolveUnknownWorkflowAttempt = `-- name: ResolveUnknownWorkflowAttempt :execrows
UPDATE workflow_attempts
SET state = ?1, lease_token = '', lease_until = NULL,
    ended_at = ?2, error_code = ?3, updated_at = ?2
WHERE id = ?4
  AND workflow_id = ?5
  AND state = 'unknown'
`

type ResolveUnknownWorkflowAttemptParams struct {
	NextState  domain.WorkflowAttemptState
	Now        sql.NullTime
	ErrorCode  string
	ID         domain.WorkflowAttemptID
	WorkflowID domain.WorkflowID
}

// Reconciliation is the only exit from UNKNOWN, and it never re-dispatches:
// the UPDATE records the outcome an operator (or reconciliation job) decided,
// which also removes the attempt from the active-attempt partial index so the
// task can move again.
func (q *Queries) ResolveUnknownWorkflowAttempt(ctx context.Context, arg ResolveUnknownWorkflowAttemptParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, resolveUnknownWorkflowAttempt,
		arg.NextState,
		arg.Now,
		arg.ErrorCode,
		arg.ID,
		arg.WorkflowID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const retryWorkflowTask = `-- name: RetryWorkflowTask :execrows
UPDATE workflow_tasks
SET state = 'ready', revision = revision + 1, updated_at = ?1
WHERE workflow_tasks.workflow_id = ?2
  AND workflow_tasks.id = ?3
  AND workflow_tasks.state = 'retry_wait'
  AND workflow_tasks.revision = ?4
  AND EXISTS (
      SELECT 1 FROM workflows
      WHERE id = ?2 AND state = 'active'
  )
  AND (
      SELECT COUNT(*) FROM workflow_attempts a
      WHERE a.workflow_id = workflow_tasks.workflow_id AND a.task_id = workflow_tasks.id
  ) < workflow_tasks.max_attempts
  AND NOT EXISTS (
      SELECT 1
      FROM workflow_edges e
      JOIN workflow_tasks predecessor
        ON predecessor.workflow_id = e.workflow_id AND predecessor.id = e.from_task_id
      WHERE e.workflow_id = ?2
        AND e.to_task_id = workflow_tasks.id
        AND predecessor.state <> 'succeeded'
  )
  AND NOT EXISTS (
      SELECT 1 FROM workflow_attempts a
      WHERE a.workflow_id = workflow_tasks.workflow_id
        AND a.task_id = workflow_tasks.id
        AND a.state IN ('claimed', 'running', 'settling', 'unknown')
  )
`

type RetryWorkflowTaskParams struct {
	UpdatedAt        time.Time
	WorkflowID       domain.WorkflowID
	TaskID           domain.WorkflowTaskID
	ExpectedRevision int64
}

func (q *Queries) RetryWorkflowTask(ctx context.Context, arg RetryWorkflowTaskParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, retryWorkflowTask,
		arg.UpdatedAt,
		arg.WorkflowID,
		arg.TaskID,
		arg.ExpectedRevision,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

