const startWorkflowAttempt = `-- name: StartWorkflowAttempt :execrows
UPDATE workflow_attempts
SET state = 'running', heartbeat_at = ?1,
    started_at = ?1, updated_at = ?1
WHERE workflow_attempts.id = ?2
  AND workflow_attempts.workflow_id = ?3
  AND workflow_attempts.state = 'claimed'
  AND workflow_attempts.lease_token = ?4
  AND lease_until > ?1
`

type StartWorkflowAttemptParams struct {
	Now        sql.NullTime
	ID         domain.WorkflowAttemptID
	WorkflowID domain.WorkflowID
	LeaseToken string
}

// Deliberately NOT gated on workflows.state = 'active': claim and retry are the
// gates that admit NEW work. A claim granted while the workflow was active must
// still be startable and settleable (drain semantics) even if a sibling task's
// terminal failure already moved the workflow to 'failed'.
func (q *Queries) StartWorkflowAttempt(ctx context.Context, arg StartWorkflowAttemptParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, startWorkflowAttempt,
		arg.Now,
		arg.ID,
		arg.WorkflowID,
		arg.LeaseToken,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

